"texto": "<p><img class=\"formula\" src=\"provas/img/2024/c3-065.png\" alt=\"fórmula (ver prova original)\" style=\"height:1.00em\"><br><img class=\"formula\" src=\"provas/img/2024/c3-066.png\" alt=\"fórmula (ver prova original)\" style=\"height:1.18em\"><br><img class=\"formula\" src=\"provas/img/2024/c3-067.png\" alt=\"fórmula (ver prova original)\" style=\"height:1.55em\"></p>",
